{
  "options": [
    {
      "id": "A",
      "summary": "离婚当天女主冷酷转身，限量跑车揭露隐藏身份，前夫跪求追妻，女主事业开挂、新恋情降临，前夫彻底追悔莫及。",
      "chapters": [
        {
          "num": 1,
          "title": "离婚签字，他以为我会哭",
          "role": "hook_open",
          "core_event": "女主冷静走进民政局，签下离婚协议，前夫携白月光施压，女主转身坐上全球限量跑车离去。",
          "emotion": "压抑后的爽快，代入女主，期待逆袭",
          "hook": "限量跑车引擎轰鸣，前夫和白月光脸色煞白，女主头也不回。",
          "beat": "【场景目的】三句话讲清丧偶式婚姻，离婚现场一刀两断，用跑车钩子宣告女主新身份。\\n【核心动作】女主提出离婚、签字、拒绝前夫施舍、亮出车钥匙、驾车离开。\\n【节奏档位】快\\n【结尾钩子】白月光尖叫：“那辆车…是她的？！”",
          "intent": {
            "ai_suggest": "离婚梗+冷漠打脸+转折+爽感代入女主"
          }
        },
        {
          "num": 2,
          "title": "全球限量跑车的主人",
          "role": "paywall",
          "core_event": "前夫和白月光跟踪女主至顶级会所，女主被曝是隐退赛车手兼品牌创始人，身份真相砸向众人。",
          "emotion": "揭秘爽感，身份反转，打脸前夫，读者痛快",
          "hook": "会所经理宣布“老板来了”，女主对前夫说：“还用我自我介绍吗？”",
          "beat": "【场景目的】马甲掉落，引爆前夫情绪，为付费后倒追蓄力。\\n【核心动作】前夫跟踪被拒、闯进会所、目睹众人簇拥女主、身份曝光、前夫震惊、女主冷漠离开。\\n【节奏档位】中快\\n【结尾钩子】前夫冲出会所大喊：“颜颜，我错了！”",
          "intent": {
            "ai_suggest": "马甲掉落+身份反转+打脸+爽感+前夫后悔"
          }
        },
        {
          "num": 3,
          "title": "前夫跪在雨里",
          "role": "paid_open",
          "core_event": "前夫雨中下跪求和，女主专注事业签下国际大单，前夫公司却突遭收购。",
          "emotion": "爽感升级，看前夫狼狈，女主事业腾飞",
          "hook": "收购协议曝光，前夫瘫坐雨中。",
          "beat": "【场景目的】展示女主事业开挂，前夫倒追不断受挫，铺垫最终打脸。\\n【核心动作】女主与男二商谈合同、签约、前夫雨中拦车下跪、女主视而不见、收购消息传来。\\n【节奏档位】快\\n【结尾钩子】前夫手机掉落，屏幕显示公司易主。"
        },
        {
          "num": 4,
          "title": "再也没有我们",
          "role": "finale",
          "core_event": "前夫破产最后挽回，女主携新男神出席活动，公开宣言自由，前夫在角落彻底失语。",
          "emotion": "极致爽感，前夫追悔莫及，女主光芒万丈",
          "hook": "女主对镜头微笑：“感谢当年不娶之恩。”",
          "beat": "【场景目的】情感闭环，女主全面获胜，前夫彻底出局，篇章收束。\\n【核心动作】前夫破产求见、女主拒绝、活动现场女主与新男神登对出入、发表感言、前夫远处观看、女主转身离开。\\n【节奏档位】中\\n【结尾钩子】女主背影融入灯光，前夫喃喃：“我弄丢了她。”",
          "intent": {
            "core_task": {
              "opening_gap": "前夫跪求别走，女主头也不回"
            },
            "freeze_frame": "女主转身时微笑的特写",
            "open_ending": "新生活璀璨开幕，前夫沉溺悔恨"
          }
        }
      ]
    }
  ]
}

{
  "summary": "问题标签为 review_gap，最可能因 review.platform 节点缺少针对番茄平台风格的强审阅规则，导致生成内容未满足首章钩子与节奏要求",
  "suspects": [
    {
      "node_id": "review.platform",
      "confidence": 0.9,
      "reason": "issue_tags 直接指向审阅缺失；用户口味库要求首章3000字内出现核心冲突或强钩子、每章结尾留悬念，而这些规则在生成后应经 review.platform 校验，但未生效。",
      "suggested_patch": "在 review.platform 的审阅指令中追加以下规则：\n1. 首章3000字内必须出现明确的核心冲突或强钩子，若未满足则直接标记并要求重写。\n2. 每章结尾必须留有悬念句或情绪钩子，若无则标记缺失。\n3. 检查并删除所有不推动情绪的铺垫句，用【删】标出。\n4. 输出评语时优先检查以上三项，缺一不可。",
      "patch_mode": "append"
    },
    {
      "node_id": "writing.main",
      "confidence": 0.5,
      "reason": "writing.main 是生成正文的节点，可能由于 beat 中未明确强调番茄平台的强钩子要求，导致产出天然缺少冲突或钩子，但 review 节点更应阻断。",
      "suggested_patch": "在 writing.main 的 prompt 开头追加“本章必须符合番茄小说节奏：首章3000字内出现核心冲突或强钩子，每章结尾留下明确的悬念句”",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "check.continuity：与连续性无关",
    "prefill.direction：用户已采纳规划与方向，方向节点正常"
  ],
  "next_action": "请确认以上 patch，然后重跑 review.platform 节点对已生成的第1章进行审阅直改，或重跑 writing.main 生成修订稿。"
}

{
  "summary": "第1章缺失平台向审阅（review.platform），导致‘review_gap’问题，未能依据硬性规则检查核心冲突开篇和钩子。",
  "suspects": [
    {
      "node_id": "review.platform",
      "confidence": 0.9,
      "reason": "证据中 prompt_node=''，且 issue_tags 仅 review_gap，表明未触发平台向审阅节点；用户口味库硬性要求‘首章3000字内出现核心冲突或强钩子’和‘每章结尾留悬念’，审阅缺失则无法保证执行。",
      "suggested_patch": "追加一条流程规则：writing.main 产出续写后，必须经 review.platform 节点进行平台向审阅。该节点需强制检查以下项目：\n1. 首章（或当前续写章）在3000字内是否出现核心冲突或立体钩子（如信息差、身份反转、强烈情绪对立）；\n2. 章末是否留有明确悬念或情绪钩子（如未解之谜、狠话、新角色介入）；\n3. 是否删去不推动情绪的铺垫句（如冗余心理、背景交代）。\n审阅不合格则打回 writing.main 修改直改稿，直至满足条件。",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "prefill.direction、prefill.plan：用户采纳方向C和规划，说明前期方向与章规节点输出被接受，非问题源头"
  ],
  "next_action": "确认 patch，将 review.platform 强制挂载到 writing.main 后，重跑第1章生成与审阅流程。建议同时检查其他章节是否同样缺失审阅。"
}

{
  "summary": "首章被拒因未满足平台强钩子规则，归因于写作节点未内嵌平台要求且审查节点缺失",
  "suspects": [
    {
      "node_id": "writing.main",
      "confidence": 0.75,
      "reason": "正文生成后出现 review_gap，直接原因是不符合番茄平台‘首章3000字内须有核心冲突/强钩子’及‘每章结尾悬念’硬性规则。口味库已记录但 prompt 未强制嵌入。",
      "suggested_patch": "在 writing.main 的 Beat 续写指令中追加规则约束：\n- 首章字数控制在3000字以内，开篇500字内明确核心冲突。\n- 章末必须设置至少一个悬念或情绪钩子（如：认知反转、身份揭示、即将爆发的矛盾）。\n- 删除不推动情绪的铺垫句，确保每段对话或动作具有推进剧情的功能。",
      "patch_mode": "append"
    },
    {
      "node_id": "review.platform",
      "confidence": 0.6,
      "reason": "缺省流程中写作后未自动调用审查节点进行女频平台向审阅，导致规则未经检验直接输出。该节点在节点列表中具备且职责匹配。",
      "suggested_patch": "在 writing.main 之后自动调度 review.platform 节点，并为其预填平台规则：\n- 检查首章3000字内核心冲突出现点。\n- 检查章末钩子是否存在且有效（识别反转、悬念、情绪断点）。\n- 若未通过，返回修改建议（非直接改稿），提示用户重跑写作。",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "prefill.direction：已采纳方向C，用户认可，不应归因。",
    "prefill.plan：规划已采纳，章节骨架无问题。",
    "check.continuity：与连续性无关，不应对本次审阅 reject 负责。"
  ],
  "next_action": "用户确认 patch 内容后，重跑 writing.main（或启用 review.platform）重新生成第1章并审阅。"
}

{
  "summary": "第一章生成后缺少平台化审阅环节，导致未检出首章强钩子等硬性要求，与历史高频 review_gap 标签吻合",
  "suspects": [
    {
      "node_id": "review.platform",
      "confidence": 0.7,
      "reason": "issue_tags 仅 review_gap，且无节点归因，结合用户口味库该标签出现2次，历史采纳规划/方向说明 prefill 节点正常，最可能为生成后未执行 review.platform 或其规则未覆盖平台硬性要求",
      "suggested_patch": "在执行 review.platform 时，追加以下审阅强制检查项：\n1. 首章3000字内是否出现核心冲突或强钩子（如反转、对峙、悬念、打脸等）。\n2. 章末是否留有至少一个明钩或暗钩（情绪钩子或情节钩子）。\n3. 是否删除了不推动情绪的铺垫句（每500字至少一个情绪转折）。\n若任一检查不通过，必须回退修改请求并给出具体位置与改法建议。",
      "patch_mode": "append"
    },
    {
      "node_id": "writing.main",
      "confidence": 0.5,
      "reason": "若 review.platform 缺失且生成文本本身未包含强钩子，可能因 writing.main 的 beat 提示不够具体，但证据不足（仅有 chapter 1 rejected），故置信度调低",
      "suggested_patch": "在 writing.main 的 beat 提示中追加一条硬性约束：\n“首章结束时必须出现一个能引发读者强烈好奇或爽感的钩子（如男主误会、身份反转、系统发布高难度任务等），且不得晚于 3000 字出现。”",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "不应甩锅给 prefill.direction 或 prefill.plan，因用户已明确‘采纳方向 C’和‘采纳规划’，说明方向与规划层未导致问题"
  ],
  "next_action": "用户确认 patch 内容后，建议先完善 review.platform 的追加指令，再重跑 review.platform 审阅已生成的第1章，或重新运行 writing.main 生成新正文并立即执行审阅"
}

{
  "summary": "正文生成后缺少平台向女频审阅环节（review.platform），导致未强制执行番茄平台的开头强钩子、章末悬念等硬性规则，用户反复标记 review_gap。",
  "suspects": [
    {
      "node_id": "review.platform",
      "confidence": 0.9,
      "reason": "issue_tags 为 review_gap 且多次拒绝均与该标签相关；用户口味库已列出多项平台硬性规则（首章3000字内必须出现核心冲突或强钩子、每章结尾须留悬念等），但生成流程中未见应用这些审阅标准，表明缺少节点调用或该节点未携带正确规则。",
      "suggested_patch": "在 review.platform 节点 prompt 中追加以下要求：\n1. 检查首章前3000字是否出现明确的核心冲突或强钩子（如对抗、反转、身份曝光），若缺失则直接改写前3段，强行插入。\n2. 每章结尾必须以一句悬念、情绪反问或未回答的疑问收束，若无则补写钩子句。\n3. 确保爽点密度：每500字至少含一个情绪转折、打脸、对比或对话翻转。\n4. 剔除不推动情绪的铺垫句，节奏保持高速。\n5. 输出时给出修改后的全文，并高亮改动处。",
      "patch_mode": "append"
    },
    {
      "node_id": "writing.main",
      "confidence": 0.5,
      "reason": "若 review.platform 已配置但未生效，可能是 writing.main 在生成时未按 Scene Beat 的‘快节奏档位’和‘离婚一刀两断’的爽点要求执行，导致产出的文字密度不足、钩子不够。但主要责任仍在审阅缺失，故此嫌疑度低。",
      "suggested_patch": "在 writing.main 的 instructions 中附加一句：'严格遵循节奏档位，每500字必须包含一次情绪转折或信息反转，结尾必须附加强钩子句，如反问或身份揭秘。'",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "prefill.direction 与 prefill.plan 不应归因；用户已明确采纳方向C和规划，说明前端的叙事设计未导致问题。"
  ],
  "next_action": "请确认上述 patch，然后重新运行第一章写作流程（prefill.plan → writing.main → review.platform），确保 review.platform 被正确调用并输出审阅后的正文。"
}

{
  "summary": "问题出在审阅阶段（review.platform），未能有效检查平台硬性钩子规则，导致原本可能合格的内容被误判或未能精准定位缺陷。生成阶段（writing.main）也可能未内嵌钩子要求，但定因在审阅反馈模糊且与用户口味中的‘review_gap’标签强相关。",
  "suspects": [
    {
      "node_id": "review.platform",
      "confidence": 0.9,
      "reason": "所有 reject 均标注 issue_tags: review_gap，且 taste_events 中 review_gap 标签出现 4 次，表明审阅节点未能识别出章节是否满足平台刚性规则（首章 3000 字内需核心冲突/强钩子、章尾悬念钩子），仅笼统反馈‘审阅缺口’。",
      "suggested_patch": "在 review.platform 的提示词中追加以下检查清单，要求逐条判定并给出精准反馈：\n1. 首章是否在 3000 字内出现核心冲突或强钩子？如否，标记缺失位置。\n2. 章末是否留有悬念、情绪转折或行为钩子？如否，指出具体段落。\n3. 全文是否存在推动情绪的无效铺垫句？如有，举例建议删除。\n审阅输出格式改为：通过/不通过 + 上述点检结果。",
      "patch_mode": "append"
    },
    {
      "node_id": "writing.main",
      "confidence": 0.65,
      "reason": "生成内容本身可能未内嵌钩子要求，因为写作提示仅依赖 scene beat 描述，而 beat 描述中虽有‘用跑车钩子宣告新身份’，但实际执行时可能未落在强悬念上，导致审阅发现缺口。间接证据：用户采纳了规划和方向，但第一章仍被拒，说明生成未达到预期钩子强度。",
      "suggested_patch": "在 writing.main 的提示词中补充一条强制规则：‘无论 scene beat 如何描述，每章结尾必须包含一个明确的趣味钩子或情绪反转，并注明钩子类型（悬念/反转/挑衅）。生成后自检是否满足本章目标钩子。’",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
    "maintain.summary：仅做概述记录，不参与内容把关。",
    "check.continuity：连续性检查与此问题无关。"
  ],
  "next_action": "确认 patch 后，先重跑 review.platform（应用追加的检查规则），用新规则重新审阅已有正文，定位具体缺失项，然后按需重调 writing.main 重新生成第 1 章。"
}

{
  "summary": "正文生成未满足番茄平台要求，缺失核心冲突与强钩子，且审阅环节存在缺口，导致输出被驳回。",
  "suspects": [
    {
      "node_id": "writing.main",
      "confidence": 0.85,
      "reason": "用户已采纳规划和方向，但生成的正文被驳回并标记为 review_gap。问题极可能出在正文执行上：场景 Beat 中虽有‘离婚签字、跑车钩子’，但生成内容未能在首章 3000 字内体现出足够强烈的冲突或悬念，不符合平台硬性要求。",
      "suggested_patch": "追加写作规则：\n- 第一章正文必须在 2000 字内出现明显的核心冲突（如对峙、反转或身份揭露），不可仅靠对话铺垫。\n- 结尾必须留下强情绪钩子（如震惊、悬念、偷听），禁止平淡收束。\n- 删去所有不推动情绪或冲突的过度描写，优先保留动作和对话。\n- 参照【Scene Beat】中的‘白月光尖叫：那辆车…是她的？！’直接作为章节结尾句生成。",
      "patch_mode": "append"
    },
    {
      "node_id": "review.platform",
      "confidence": 0.7,
      "reason": "标签‘review_gap’直接暗示审阅环节存在盲区。该节点本应模拟平台审阅并提供直改建议，但可能未被触发或规则未包含特定平台硬性指标，导致质量缺口未被发现。",
      "suggested_patch": "追加审阅清单：\n- 检查第一章 3000 字内是否出现核心冲突或强钩子（是/否）。\n- 检查结尾是否有悬念或情绪钩子（是/否）。\n- 检查是否有可通过删除而不影响情节的铺垫句，若有则标记。\n- 检查字数是否在 2000~3000 字区间。\n- 若以上任一未达标，直接输出修改版正文，并标注改动理由。",
      "patch_mode": "append"
    }
  ],
  "avoid_nodes": [
